use std::{alloc::{GlobalAlloc, Layout, System}, hint::black_box, sync::atomic::{AtomicUsize, Ordering}};
struct CountingSystem;
static LIVE: AtomicUsize = AtomicUsize::new(0);
static PEAK: AtomicUsize = AtomicUsize::new(0);
static CALLS: AtomicUsize = AtomicUsize::new(0);
fn add(size: usize) {
    let live = LIVE.fetch_add(size, Ordering::Relaxed) + size;
    PEAK.fetch_max(live, Ordering::Relaxed);
    CALLS.fetch_add(1, Ordering::Relaxed);
}
// The isolated probe delegates every allocation unchanged to System. Counts
// cover requested Rust allocation sizes, excluding allocator headers and C APIs.
unsafe impl GlobalAlloc for CountingSystem {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let ptr = unsafe { System.alloc(layout) };
        if !ptr.is_null() { add(layout.size()); }
        ptr
    }
    unsafe fn dealloc(&self, ptr: *mut u8, layout: Layout) {
        LIVE.fetch_sub(layout.size(), Ordering::Relaxed);
        unsafe { System.dealloc(ptr, layout); }
    }
    unsafe fn realloc(&self, ptr: *mut u8, layout: Layout, new_size: usize) -> *mut u8 {
        let resized = unsafe { System.realloc(ptr, layout, new_size) };
        if !resized.is_null() {
            LIVE.fetch_sub(layout.size(), Ordering::Relaxed);
            add(new_size);
        }
        resized
    }
    unsafe fn alloc_zeroed(&self, layout: Layout) -> *mut u8 {
        let ptr = unsafe { System.alloc_zeroed(layout) };
        if !ptr.is_null() { add(layout.size()); }
        ptr
    }
}
#[global_allocator]
static ALLOCATOR: CountingSystem = CountingSystem;
fn snapshot() -> (usize,usize,usize) {
    (LIVE.load(Ordering::Relaxed), PEAK.load(Ordering::Relaxed), CALLS.load(Ordering::Relaxed))
}
fn main() {
    // Complete formatting only after every phase sample to avoid retaining an
    // output buffer inside the constructor/repetition deltas.
    let before = snapshot();
    let direct = tiktoken_rs::cl100k_base().unwrap();
    let after_construct = snapshot();
    let inputs = ["", "pub fn unchanged() -> usize { 123 }\n", "漢字 café 🙂", " \n\t 123456789"];
    let expected = inputs.map(|text| direct.encode_ordinary(text));
    let before_repeat = snapshot();
    for _ in 0..100 {
        for (text,tokens) in inputs.iter().zip(expected.iter()) {
            assert_eq!(&black_box(direct.encode_ordinary(text)),tokens);
        }
    }
    let after_repeat = snapshot();
    drop(expected);drop(direct);
    let after_drop = snapshot();
    let singleton = tiktoken_rs::cl100k_base_singleton();
    let after_singleton = snapshot();
    let first_pointer = singleton as *const _;
    for _ in 0..100 {
        assert_eq!(first_pointer,tiktoken_rs::cl100k_base_singleton() as *const _);
        for text in inputs { black_box(singleton.encode_ordinary(text)); }
    }
    let after_singleton_repeat = snapshot();
    println!("{{\"before\":{:?},\"after_construct\":{:?},\"before_repeat\":{:?},\"after_repeat\":{:?},\"after_drop\":{:?},\"after_singleton\":{:?},\"after_singleton_repeat\":{:?}}}",before,after_construct,before_repeat,after_repeat,after_drop,after_singleton,after_singleton_repeat);
}

