use std::collections::HashSet;
use old_token::CoreBPE as Old;
use new_token::CoreBPE as New;
fn compare(name: &str, old: Old, new: New) {
 let mut decoded=0usize;let mut valid_utf8=0usize;
 for rank in 0..201_500u32 {
  match (old.decode_bytes(&[rank]),new.decode_bytes(&[rank])) {
   (Ok(a),Ok(b)) => {assert_eq!(a,b,"{name} rank {rank}");decoded+=1;
    if let Ok(text)=std::str::from_utf8(&a) {assert_eq!(old.encode_ordinary(text),new.encode_ordinary(text),"{name} decoded rank {rank}");valid_utf8+=1;}
   }
   (Err(a),Err(b)) => assert_eq!(a.token,b.token,"{name} invalid rank {rank}"),
   _ => panic!("{name} valid rank disagreement {rank}"),
  }
 }
 assert_eq!(old.special_tokens(),new.special_tokens());
 let old_special=old.special_tokens();let new_special=new.special_tokens();
 let empty=HashSet::new();
 let fixed=["", "hello world", "漢字 café 🙂", "e\u{301} café\r\n", "\0\t\r\n ", "pub fn unchanged() -> usize { 123456789 }", "<|endoftext|>", "<|fim_prefix|>x<|fim_middle|>", "<|im_start|>assistant<|im_sep|>", "𝓤𐐷👨‍👩‍👧‍👦", " \n\n  ", "abc '.local/share' target/a.rs", "a" ];
 let mut corpus:Vec<String>=fixed.iter().map(|x|x.to_string()).collect();
 let alphabet=['a','A','0','9',' ','\n','\r','\t','é','漢','🙂','\u{301}','<','|','>','_','/', '.', '𐐷'];let mut seed=0x604636u64;
 for case in 0..200 {
  let mut text=String::new();
  for _ in 0..(1+case%96) {seed=seed.wrapping_mul(6364136223846793005).wrapping_add(1);text.push(alphabet[(seed>>32) as usize%alphabet.len()]);}
  corpus.push(text);
 }
 for text in &corpus {
  assert_eq!(old.encode_ordinary(text),new.encode_ordinary(text),"{name} ordinary {text:?}");
  assert_eq!(old.encode_with_special_tokens(text),new.encode_with_special_tokens(text),"{name} special {text:?}");
  assert_eq!(old.encode(text,&empty).map_err(|e|e.to_string()),new.encode(text,&empty).map_err(|e|e.to_string()),"{name} disallowed special {text:?}");
  assert_eq!(old.encode(text,&old_special).map_err(|e|e.to_string()),new.encode(text,&new_special).map_err(|e|e.to_string()),"{name} allowed special {text:?}");
  let tokens=old.encode_ordinary(text);
  assert_eq!(old._decode_native_and_split(tokens.clone()).collect::<Vec<_>>(),new._decode_native_and_split(tokens).collect::<Vec<_>>(),"{name} owned token bytes");
 }
 for text in corpus.iter().take(32) {
  assert_eq!(old._encode_unstable_native(text,&old_special),new._encode_unstable_native(text,&new_special),"{name} unstable {text:?}");
 }
 let old_clone=old.clone();let new_clone=new.clone();drop(old_special);drop(new_special);drop(old);drop(new);
 for text in corpus.iter().take(32) {assert_eq!(old_clone.encode_ordinary(text),new_clone.encode_ordinary(text),"{name} clone after original drop");}
 println!("{{\"encoding\":\"{name}\",\"rank_checks\":201500,\"valid_decoded_ranks\":{decoded},\"decoded_utf8_encode_checks\":{valid_utf8},\"corpus_cases\":{},\"unstable_cases\":32,\"clone_after_drop_cases\":32}}",corpus.len());
}
fn main() {
 compare("r50k_base",old_token::r50k_base().unwrap(),new_token::r50k_base().unwrap());
 compare("p50k_base",old_token::p50k_base().unwrap(),new_token::p50k_base().unwrap());
 compare("p50k_edit",old_token::p50k_edit().unwrap(),new_token::p50k_edit().unwrap());
